/*
 * Recognition, daily profile and network of the model generated by ml/train.py (anomaly_model.h).
 * float32 only, no libm, no heap. Every operation runs in the order of ml/features.py, so results are
 * bit-identical when compiled without fused multiply-add (-ffp-contract=off, see CMakeLists.txt).
 */
#include "anomaly.h"
#include "anomaly_model.h"

_Static_assert(AD_NFEAT == 6 && AD_NCTX == 8, "feature and context lists must match ml/features.py");

const float ad_thr_basic = AD_THR_BASIC;
const float ad_thr_full = AD_THR_FULL;

static const float log2_c[] = {AD_LOG2_C};
static const float exp2_c[] = {AD_EXP2_C};

typedef union {
	float f;
	uint32_t u;
	int32_t i;
} ad_bits_t;

static inline float ad_absf(float a)
{
	return a < 0.0f ? -a : a;
}

static inline float ad_maxf(float a, float b)
{
	return a > b ? a : b;
}

/* log2(x) = exponent + m * q(m), m = mantissa - 1 in [0, 1) */
static float ad_log2(float x)
{
	ad_bits_t v = {.f = x};
	float e = (float)((int32_t)(v.u >> 23) - 127);

	v.u = (v.u & 0x007FFFFFu) | 0x3F800000u;
	float m = v.f - 1.0f;
	float p = log2_c[4];

	for (int k = 3; k >= 0; k--) {
		p = p * m + log2_c[k];
	}
	return e + m * p;
}

/* 2^x = 2^floor(x) * (1 + f * r(f)), f in [0, 1) */
static float ad_exp2(float x)
{
	x = x < -60.0f ? -60.0f : (x > 60.0f ? 60.0f : x);
	int32_t i = (int32_t)x;

	if ((float)i > x) {
		i--;
	}
	float f = x - (float)i;
	float p = exp2_c[3];

	for (int k = 2; k >= 0; k--) {
		p = p * f + exp2_c[k];
	}
	ad_bits_t v = {.f = 1.0f + f * p};

	v.i += i * (1 << 23);
	return v.f;
}

void ad_init(ad_state_t *s)
{
	*s = (ad_state_t){0};
	s->cur_slot = -1;
	s->floor = AD_DFLOOR;
}

int ad_feed(ad_state_t *s, uint32_t sec_of_day, float x)
{
	if (s->n == 0) {
		s->x0 = x;
		s->sum = s->sumsq = s->dsum = s->dmax = 0.0f;
	}
	float d = x - s->x0;

	s->sum += d;
	s->sumsq += d * d;
	if (s->has_prev) {
		float a = ad_absf(x - s->prev);

		s->dsum += a;
		if (a > s->dmax) {
			s->dmax = a;
		}
	}
	s->prev = x;
	s->has_prev = 1;
	s->sec = sec_of_day;
	return ++s->n >= AD_WINDOW;
}

/* Learn the slot that just ended. The first learning is postponed once if the slot raised an alarm
 * (accepted the second time, so recurring patterns get learned); later days move the slot by a
 * clipped running mean, so a single anomalous day cannot drag it far. */
static void ad_finalize_slot(ad_state_t *s)
{
	if (s->acc_cnt < AD_MINCNT) {
		return;
	}
	const int k = s->cur_slot;
	const float t = s->acc_sum / (float)s->acc_cnt;
	const uint8_t n = s->meta[k] & 0x0F;

	if (n == 0) {
		if (!s->acc_alarm || (s->meta[k] & 0x80)) {
			s->m[k] = t;
			s->d[k] = 0.0f;
			s->meta[k] = 1;
		} else {
			s->meta[k] |= 0x80;
		}
		return;
	}
	const float lim = AD_CLIP_K * ad_maxf(s->d[k], s->floor);
	float e = t - s->m[k];

	if (e > lim) {
		e = lim;
	} else if (e < -lim) {
		e = -lim;
	}
	s->d[k] += (ad_absf(e) - s->d[k]) / (float)(n < AD_NMAX ? n : AD_NMAX);
	s->m[k] += e / (float)(n + 1 < AD_NMAX ? n + 1 : AD_NMAX);
	s->meta[k] = n + 1 < AD_NMAX ? n + 1 : AD_NMAX;
}

ad_result_t ad_run_inference(ad_state_t *s)
{
	const float inv_w = 1.0f / AD_WINDOW;
	const float mm = s->sum * inv_w;
	const float mean = s->x0 + mm;
	float var = s->sumsq * inv_w - mm * mm;

	if (var < 0.0f) {
		var = 0.0f;
	}
	const float lstd = 0.5f * ad_log2(var + AD_EPS_VAR);
	const float ldmax = ad_log2(s->dmax + AD_EPS_RNG);
	const float ldabs = ad_log2(s->dsum * inv_w + AD_EPS_RNG);

	if (s->k == 0) {
		s->ema = mean;
	}
	const float trend = mean - s->ema;

	s->ema += AD_EMA_ALPHA * (mean - s->ema);
	s->n = 0;

	const int16_t slot = (int16_t)(s->sec / AD_SLOT_SEC);

	if (slot != s->cur_slot) {
		if (s->cur_slot >= 0) {
			ad_finalize_slot(s);
		}
		s->cur_slot = slot;
		s->acc_sum = 0.0f;
		s->acc_cnt = 0;
		s->acc_alarm = 0;
	}

	ad_result_t r = {0.0f, AD_LEARNING, 0};

	if (s->k < AD_RECOG) {
		if (s->k == 0) {
			s->L0 = mean; /* origin of the recognition sums */
		}
		const float dm = mean - s->L0;

		s->rs += dm;
		s->rq += dm * dm;
		s->Bs += lstd;
		s->Bm += ldmax;
		s->Ba += ldabs;
		if (s->k == AD_RECOG - 1) {
			const float inv_r = 1.0f / AD_RECOG;
			const float mr = s->rs * inv_r;
			float v = s->rq * inv_r - mr * mr;

			if (v < 0.0f) {
				v = 0.0f;
			}
			s->L0 += mr;
			s->swing = 0.5f * ad_log2(v + AD_EPS_VAR);
			s->Bs *= inv_r;
			s->Bm *= inv_r;
			s->Ba *= inv_r;
			s->floor = ad_maxf(AD_DFLOOR, ad_exp2(s->Bs));
		}
	} else {
		/* reference: learned profile at this time of day (interpolated between slot centres),
		 * or the recognised level while that time of day is not learned yet */
		int32_t q = (int32_t)s->sec - AD_SLOT_SEC / 2;

		if (q < 0) {
			q += 86400;
		}
		const int s0 = q / AD_SLOT_SEC;
		const int s1 = s0 + 1 == AD_SLOTS ? 0 : s0 + 1;
		const float f = (float)(q % AD_SLOT_SEC) * (1.0f / AD_SLOT_SEC);
		const uint8_t n0 = s->meta[s0] & 0x0F, n1 = s->meta[s1] & 0x0F;
		const int ready = n0 > 0 && n1 > 0;
		float ref = s->L0, slope = 0.0f, dd = 0.0f, nn = 0.0f;

		if (ready) {
			slope = s->m[s1] - s->m[s0];
			ref = s->m[s0] + f * slope;
			dd = s->d[s0] + f * (s->d[s1] - s->d[s0]);
			nn = (float)(n0 < n1 ? n0 : n1);
		}
		const float asl = ad_absf(slope);
		const float c[AD_NCTX] = {
			(float)ready,
			(float)(s->k < AD_DAY_WIN ? s->k : AD_DAY_WIN) * (1.0f / AD_DAY_WIN),
			ad_log2(asl + AD_EPS_SL),
			slope / (asl + AD_EPS_SL),
			ad_log2(dd + AD_EPS_D),
			nn * (1.0f / AD_NMAX),
			s->Bs,
			s->swing,
		};
		const float y[AD_NFEAT] = {
			mean - ref, s->ema - ref, trend, lstd - s->Bs, ldmax - s->Bm, ldabs - s->Ba,
		};
		float h[AD_HIDDEN];

		for (int j = 0; j < AD_HIDDEN; j++) {
			float a = ad_b1[j];

			for (int i = 0; i < AD_NCTX; i++) {
				a += ad_w1[j][i] * c[i];
			}
			h[j] = a > 0.0f ? a : 0.0f;
		}

		/* expected value mu and log2 precision beta of every feature in this context */
		float acc = 0.0f;

		for (int o = 0; o < AD_NFEAT; o++) {
			float mu = ad_b2[o];
			float be = ad_b2[AD_NFEAT + o];

			for (int j = 0; j < AD_HIDDEN; j++) {
				mu += ad_w2[o][j] * h[j];
				be += ad_w2[AD_NFEAT + o][j] * h[j];
			}
			const float z = (y[o] - mu) * ad_exp2(be);

			acc += z * z;
		}
		r.score = acc * (1.0f / AD_NFEAT);
		r.phase = ready ? AD_FULL : AD_BASIC;
		r.anomaly = r.score >= (ready ? ad_thr_full : ad_thr_basic);
	}
	s->acc_sum += mean;
	s->acc_cnt++;
	s->acc_alarm |= r.anomaly;
	s->k++;
	return r;
}
